css:
.accident-print-title { text-align: center; margin-bottom: 4px; }
.accident-print-sub { text-align: center; color: #666; margin-bottom: 18px; }
.accident-section-title { background: #f2f2f2; padding: 6px 10px; font-weight: bold; margin-top: 16px; border-left: 4px solid #C0392B; }
.accident-table { width: 100%; border-collapse: collapse; margin-top: 6px; }
.accident-table td { padding: 5px 8px; vertical-align: top; border-bottom: 1px solid #eee; }
.accident-label { color: #555; width: 220px; font-weight: bold; }
.accident-signature-block { margin-top: 40px; display: flex; justify-content: space-between; }
.accident-signature-line { border-top: 1px solid #333; width: 260px; padding-top: 4px; margin-top: 40px; text-align: center; }
.severity-badge { padding: 2px 10px; border-radius: 10px; color: #fff; font-weight: bold; font-size: 12px; }
.severity-Minor { background: #7f8c8d; }
.severity-Moderate { background: #E67E22; }
.severity-Major { background: #C0392B; }
.severity-Fatal { background: #000; }
